mapper.select:
SELECT l.id,
       l.trace_id,
       l.user_id,
       l.module,
       l.operate_type,
       l.target_table,
       l.target_id,
       l.created_at
FROM sys_operate_logs l
INNER JOIN enterprise_team_members m
    ON m.user_id = l.user_id
    AND m.enterprise_id = #{enterpriseId}
    AND m.is_deleted = FALSE
WHERE l.is_deleted = FALSE

    AND l.module = #{module}


    AND l.operate_type = #{operateType}


    AND l.target_table = #{targetTable}


    AND l.target_id = #{targetId}


    AND l.created_at >= #{startTime}


    AND l.created_at <= #{endTime}

ORDER BY l.created_at DESC, l.id DESC
